79	type deleteAttachmentStorageFailpointKey struct{}
80	
81	// ErrDeleteAttachmentStorageFailpoint is returned by the test-only attachment storage failpoint.
82	var ErrDeleteAttachmentStorageFailpoint = errors.New("delete attachment storage failpoint")
83	
84	// WithDeleteAttachmentStorageFailpoint forces DeleteAttachmentStorage to return a failpoint error.
85	func WithDeleteAttachmentStorageFailpoint(ctx context.Context) context.Context {
86		return context.WithValue(ctx, deleteAttachmentStorageFailpointKey{}, true)
87	}
