5	// UserIdentity is the linkage between an external identity subject and a local user.
6	// Uniqueness is enforced on (Provider, ExternUID); one local user may have multiple
7	// identities across different providers.
8	type UserIdentity struct {
9		ID        int32
10		UserID    int32
11		Provider  string
12		ExternUID string
13		CreatedTs int64
14		UpdatedTs int64
15	}
