18	type FindUserIdentity struct {
19		ID        *int32
20		UserID    *int32
21		Provider  *string
22		ExternUID *string
23	}
24	
25	// DeleteUserIdentity is used to delete user identity linkage rows.
26	type DeleteUserIdentity struct {
27		ID       *int32
28		UserID   *int32
29		Provider *string
30	}
