32	// CreateUserIdentity creates a new external-identity linkage record.
33	// Returns the driver error on unique-constraint violation; callers are responsible
34	// for reconciling concurrent first-login races on (Provider, ExternUID).
35	func (s *Store) CreateUserIdentity(ctx context.Context, create *UserIdentity) (*UserIdentity, error) {
36		return s.driver.CreateUserIdentity(ctx, create)
37	}
