41		return s.driver.ListUserIdentities(ctx, find)
42	}
43	
44	// DeleteUserIdentities deletes all linkage records matching the filter.
45	func (s *Store) DeleteUserIdentities(ctx context.Context, delete *DeleteUserIdentity) error {
46		return s.driver.DeleteUserIdentities(ctx, delete)
47	}
48	
49	// GetUserIdentity returns the first linkage record matching the filter, or nil if none found.
50	func (s *Store) GetUserIdentity(ctx context.Context, find *FindUserIdentity) (*UserIdentity, error) {
51		list, err := s.ListUserIdentities(ctx, find)
52		if err != nil {
53			return nil, err
54		}
55		if len(list) == 0 {
56			return nil, nil
57		}
58		return list[0], nil
59	}
